create or replace function public.srk_customer_choose_payment_method(p_booking_id uuid,p_method text)
returns public.service_bookings
language plpgsql security definer
set search_path=pg_catalog,public,auth
as $$
declare v_booking public.service_bookings%rowtype; v_forced_online boolean;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if lower(p_method) not in ('cash','online','upi','card') then raise exception 'Choose Cash, Online, UPI or Card'; end if;
  select * into v_booking from public.service_bookings
  where id=p_booking_id and customer_user_id=auth.uid() for update;
  if not found then raise exception 'Customer booking not found'; end if;
  if v_booking.payment_status='paid' then raise exception 'Payment is already completed'; end if;
  if not exists(select 1 from public.srk_booking_final_bills where booking_id=p_booking_id and status in ('issued','approved')) then
    raise exception 'Payment method can be selected after the final bill is issued';
  end if;
  select exists(
    select 1 from public.srk_booking_workers bw
    join public.srk_technician_booking_cycle c on c.technician_id=bw.worker_id
    where bw.booking_id=p_booking_id and bw.worker_role='technician'
      and (c.completed_booking_count+1) in (3,6)
  ) into v_forced_online;
  if v_forced_online and lower(p_method)='cash' then raise exception 'This technician booking requires online payment'; end if;
  update public.service_bookings set payment_method=case when lower(p_method) in ('upi','card') then initcap(lower(p_method)) else initcap(lower(p_method)) end
  where id=p_booking_id returning * into v_booking;
  return v_booking;
end $$;
revoke all on function public.srk_customer_choose_payment_method(uuid,text) from public,anon;
grant execute on function public.srk_customer_choose_payment_method(uuid,text) to authenticated;

create or replace function public.srk_on_booking_payment_completed()
returns trigger language plpgsql security definer
set search_path=pg_catalog,public,auth
as $$
declare v_bw record; v_count bigint; v_next bigint; v_method text; v_normalized_method text;
begin
  if new.status='completed'
     and lower(coalesce(new.payment_status,'')) in ('paid','completed')
     and not (old.status='completed' and lower(coalesce(old.payment_status,'')) in ('paid','completed')) then
    v_method:=lower(coalesce(new.payment_method,''));
    v_normalized_method:=case when v_method in ('upi','card') then 'online' else v_method end;
    for v_bw in
      select bw.worker_id
      from public.srk_booking_workers bw
      join public.srk_worker_profiles wp on wp.id=bw.worker_id
      where bw.booking_id=new.id and bw.worker_role='technician'
        and wp.worker_type='technician' and bw.assignment_status in ('completed','released')
      order by bw.worker_id
    loop
      insert into public.srk_technician_booking_cycle(technician_id)
      values(v_bw.worker_id) on conflict(technician_id) do nothing;
      select completed_booking_count into v_count
      from public.srk_technician_booking_cycle where technician_id=v_bw.worker_id for update;
      v_next:=v_count+1;
      if v_next in (3,6) and v_method not in ('online','upi','card') then
        raise exception 'Technician completed booking number % must be paid online',v_next;
      end if;
      update public.srk_technician_booking_cycle
        set completed_booking_count=v_next,last_completed_at=clock_timestamp(),updated_at=clock_timestamp()
      where technician_id=v_bw.worker_id;
      insert into public.srk_technician_booking_sequence(technician_id,booking_id,sequence_number,payment_method)
      values(v_bw.worker_id,new.id,v_next,v_normalized_method)
      on conflict(technician_id,booking_id) do nothing;
    end loop;

    update public.srk_worker_earnings set payment_method=v_normalized_method,updated_at=clock_timestamp()
    where booking_id=new.id;
    perform public.srk_post_one_worker_earning(e.id)
      from public.srk_worker_earnings e where e.booking_id=new.id;
  end if;
  return new;
end $$;

create or replace function public.srk_worker_complete_assignment(p_booking_worker_id uuid,p_note text default null)
returns public.srk_booking_workers
language plpgsql security definer
set search_path=pg_catalog,public,auth
as $$
declare v_assignment public.srk_booking_workers%rowtype; v_remaining integer; v_total_seconds bigint;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  select bw.* into v_assignment from public.srk_booking_workers bw
  join public.srk_worker_profiles wp on wp.id=bw.worker_id
  where bw.id=p_booking_worker_id and wp.user_id=auth.uid() for update of bw;
  if not found then raise exception 'Assignment not found or not yours'; end if;
  if not exists(select 1 from public.srk_worker_work_sessions where booking_worker_id=p_booking_worker_id) then
    raise exception 'At least one work session is required';
  end if;
  if exists(select 1 from public.srk_worker_work_sessions where booking_worker_id=p_booking_worker_id and session_status not in ('completed','cancelled')) then
    raise exception 'Complete or cancel every daily work session first';
  end if;
  select coalesce(sum(billable_seconds),0) into v_total_seconds
  from public.srk_worker_work_sessions where booking_worker_id=p_booking_worker_id;
  if v_total_seconds<=0 then raise exception 'No billable work time recorded; Admin must release this assignment or arrange more work'; end if;

  update public.srk_booking_workers set assignment_status='completed',released_at=clock_timestamp(),
    updated_at=clock_timestamp(),admin_note=coalesce(p_note,admin_note)
  where id=p_booking_worker_id and assignment_status<>'completed' returning * into v_assignment;

  select count(*) into v_remaining from public.srk_booking_workers
  where booking_id=v_assignment.booking_id and assignment_status not in ('completed','released','cancelled','rejected');
  if v_remaining=0 then
    update public.service_bookings set status='in_progress',completion_approval_status='pending',
      completion_requested_at=clock_timestamp(),work_timer_running=false
    where id=v_assignment.booking_id and status<>'completed';
  end if;
  return v_assignment;
end $$;

create or replace function public.srk_customer_respond_multi_worker_completion(
 p_booking_id uuid,p_response text,p_note text default null
) returns jsonb
language plpgsql security definer
set search_path=pg_catalog,public,auth
as $$
declare v_booking public.service_bookings%rowtype;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if p_response not in ('approved','rejected','disputed') then raise exception 'Invalid completion response'; end if;
  select * into v_booking from public.service_bookings where id=p_booking_id and customer_user_id=auth.uid() for update;
  if not found then raise exception 'Customer booking not found'; end if;
  if not exists(select 1 from public.srk_booking_workers where booking_id=p_booking_id) then raise exception 'Not a multi-worker booking'; end if;
  if v_booking.completion_approval_status<>'pending' or v_booking.completion_requested_at is null then
    raise exception 'No completion request waiting for response';
  end if;
  if not exists(select 1 from public.srk_booking_final_bills where booking_id=p_booking_id and status='issued') then
    raise exception 'Final bill must be issued before completion approval';
  end if;

  if p_response='approved' then
    update public.service_bookings set status='completed',completion_approval_status='approved',
      customer_completed_at=clock_timestamp(),work_timer_running=false
    where id=p_booking_id;
  elsif p_response='rejected' then
    update public.service_bookings set completion_approval_status='rejected',completion_requested_at=null
    where id=p_booking_id;
    insert into public.srk_support_cases(booking_id,raised_by,raised_by_role,category,subject,description,priority)
    values(p_booking_id,auth.uid(),'customer','completion','Customer rejected completion',
      coalesce(p_note,'Customer requested review of completed work.'),'high');
  else
    if length(coalesce(p_note,''))<20 then raise exception 'Dispute reason must be at least 20 characters'; end if;
    update public.service_bookings set completion_approval_status='disputed',work_timer_running=false
    where id=p_booking_id;
    insert into public.srk_support_cases(booking_id,raised_by,raised_by_role,category,subject,description,priority)
    values(p_booking_id,auth.uid(),'customer','completion','Completion dispute',p_note,'high');
  end if;
  return jsonb_build_object('success',true,'response',p_response);
end $$;

create or replace function public.srk_customer_choose_payment_method(p_booking_id uuid,p_method text)
returns public.service_bookings
language plpgsql security definer
set search_path=pg_catalog,public,auth
as $$
declare v_booking public.service_bookings%rowtype; v_forced_online boolean;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if lower(p_method) not in ('cash','online','upi','card') then raise exception 'Choose Cash, Online, UPI or Card'; end if;
  select * into v_booking from public.service_bookings where id=p_booking_id and customer_user_id=auth.uid() for update;
  if not found then raise exception 'Customer booking not found'; end if;
  if v_booking.status<>'completed' then raise exception 'Payment can be selected after customer confirms completed work'; end if;
  if v_booking.payment_status='paid' then raise exception 'Payment is already completed'; end if;
  if not exists(select 1 from public.srk_booking_final_bills where booking_id=p_booking_id and status in ('issued','approved')) then
    raise exception 'Final bill is not available';
  end if;
  select exists(select 1 from public.srk_booking_workers bw
    join public.srk_technician_booking_cycle c on c.technician_id=bw.worker_id
    where bw.booking_id=p_booking_id and bw.worker_role='technician' and (c.completed_booking_count+1) in (3,6))
  into v_forced_online;
  if v_forced_online and lower(p_method)='cash' then raise exception 'This technician booking requires online payment'; end if;
  update public.service_bookings set payment_method=initcap(lower(p_method)) where id=p_booking_id returning * into v_booking;
  return v_booking;
end $$;

create or replace function public.srk_confirm_cash_payment(p_booking_id uuid,p_amount numeric,p_note text default null)
returns boolean
language plpgsql security definer
set search_path=pg_catalog,public,auth
as $$
declare
  v_role text; v_bill numeric(12,2); v_customer uuid; v_booking_status text; v_worker boolean;
  v_customer_confirmed boolean; v_worker_confirmed boolean; v_forced_online integer;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  select customer_user_id,status into v_customer,v_booking_status
  from public.service_bookings where id=p_booking_id for update;
  if not found then raise exception 'Booking not found'; end if;
  if v_booking_status<>'completed' then raise exception 'Customer must confirm completed work before cash payment'; end if;

  if v_customer=auth.uid() then v_role:='customer';
  else
    select exists(select 1 from public.srk_booking_workers bw join public.srk_worker_profiles wp on wp.id=bw.worker_id
      where bw.booking_id=p_booking_id and bw.worker_role='technician' and wp.user_id=auth.uid()
        and bw.assignment_status in ('assigned','working','paused','completed')) into v_worker;
    if not v_worker then raise exception 'Only booking customer or assigned Technician can confirm cash'; end if;
    v_role:='technician';
  end if;

  select total_amount into v_bill from public.srk_booking_final_bills
  where booking_id=p_booking_id and status in ('issued','approved');
  if v_bill is null then raise exception 'Final bill is not issued'; end if;
  if p_amount is null or p_amount<>v_bill then raise exception 'Cash confirmation must match final bill amount'; end if;

  if v_role='customer' then
    select count(*) into v_forced_online
    from public.srk_booking_workers bw
    join public.srk_worker_profiles wp on wp.id=bw.worker_id
    left join public.srk_technician_booking_cycle c on c.technician_id=wp.id
    where bw.booking_id=p_booking_id and bw.worker_role='technician'
      and (coalesce(c.completed_booking_count,0)+1) in (3,6);
    if v_forced_online>0 then raise exception 'This technician booking requires online payment'; end if;
  end if;

  if not exists(select 1 from public.srk_booking_payment_evidence where booking_id=p_booking_id
    and payer_role=v_role and payment_method='cash' and amount=v_bill and verification_status='verified') then
    insert into public.srk_booking_payment_evidence(booking_id,submitted_by,payer_role,payment_method,amount,verification_status,note)
    values(p_booking_id,auth.uid(),v_role,'cash',p_amount,'verified',p_note);
  end if;

  select exists(select 1 from public.srk_booking_payment_evidence where booking_id=p_booking_id and payer_role='customer' and payment_method='cash' and amount=v_bill and verification_status='verified'),
         exists(select 1 from public.srk_booking_payment_evidence where booking_id=p_booking_id and payer_role='technician' and payment_method='cash' and amount=v_bill and verification_status='verified')
  into v_customer_confirmed,v_worker_confirmed;

  if v_customer_confirmed and v_worker_confirmed then
    update public.service_bookings set payment_status='paid',amount_paid=v_bill,payment_verified_at=clock_timestamp()
    where id=p_booking_id;
    return true;
  end if;
  return false;
end $$;

create or replace function public.srk_worker_update_payout_details(p_upi_id text,p_bank_account_last4 text)
returns public.srk_worker_profiles
language plpgsql security definer
set search_path=pg_catalog,public,auth
as $$
declare v public.srk_worker_profiles%rowtype;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if p_upi_id is not null and p_upi_id !~ '^[A-Za-z0-9._-]{2,100}@[A-Za-z0-9.-]{2,50}$' then
    raise exception 'Invalid UPI ID format';
  end if;
  if p_bank_account_last4 is not null and p_bank_account_last4 !~ '^[0-9]{4}$' then
    raise exception 'Bank account last four digits must be four numbers';
  end if;
  update public.srk_worker_profiles set upi_id=p_upi_id,bank_account_last4=p_bank_account_last4,updated_at=clock_timestamp()
  where user_id=auth.uid() returning * into v;
  if not found then raise exception 'Worker profile not found'; end if;
  return v;
end $$;
revoke all on function public.srk_worker_update_payout_details(text,text) from public,anon;
grant execute on function public.srk_worker_update_payout_details(text,text) to authenticated;

create or replace function public.srk_log_booking_worker_event()
returns trigger language plpgsql security definer
set search_path=pg_catalog,public,auth
as $$
declare v_event text; v_reason text;
begin
  if tg_op='INSERT' then v_event:=new.assignment_status;
  elsif new.assignment_status is distinct from old.assignment_status then v_event:=new.assignment_status;
  else return new;
  end if;
  v_reason:=coalesce(new.admin_note,'');
  insert into public.srk_booking_worker_events(booking_worker_id,booking_id,worker_id,event_type,actor_user_id,reason,details)
  values(new.id,new.booking_id,new.worker_id,v_event,auth.uid(),v_reason,jsonb_build_object('role',new.worker_role));
  return new;
end $$;
revoke all on function public.srk_log_booking_worker_event() from public,anon,authenticated;

create or replace function public.srk_notify_admin_permission_team()
returns trigger language plpgsql security definer
set search_path=pg_catalog,public
as $$
declare v_permission text; v_title text; v_body text; v_booking uuid;
begin
  v_permission:=tg_argv[0];
  v_title:=tg_argv[1];
  v_body:=tg_argv[2];
  v_booking:=nullif(to_jsonb(new)->>'booking_id','')::uuid;

  insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
  select user_id,'admin_action_required',v_title,v_body,v_booking
  from public.srk_admin_users
  union
  select sm.user_id,'admin_action_required',v_title,v_body,v_booking
  from public.srk_admin_staff_members sm
  join public.srk_admin_roles r on r.id=sm.role_id and r.is_active
  join public.srk_admin_role_permissions rp on rp.role_id=r.id and rp.permission_code=v_permission
  where sm.is_active;
  return new;
end $$;

drop trigger if exists srk_support_case_admin_notification_trigger on public.srk_support_cases;
create trigger srk_support_case_admin_notification_trigger after insert on public.srk_support_cases
for each row execute function public.srk_notify_admin_permission_team('support.manage','New support case','A new customer/worker support case needs review.');

drop trigger if exists srk_payment_dispute_admin_notification_trigger on public.srk_booking_payment_disputes;
create trigger srk_payment_dispute_admin_notification_trigger after insert on public.srk_booking_payment_disputes
for each row execute function public.srk_notify_admin_permission_team('payments.read','New payment dispute','A payment dispute needs Admin review.');

create or replace function public.srk_on_emergency_notification()
returns trigger language plpgsql security definer
set search_path=pg_catalog,public
as $$
begin
  perform public.srk_notify_admin_permission_team('support.manage','Emergency Alert','An emergency alert requires immediate Admin attention.');
  return new;
end $$;

create or replace function public.srk_on_worker_payout_notification()
returns trigger language plpgsql security definer
set search_path=pg_catalog,public
as $$
declare v_user uuid;
begin
  if tg_op='INSERT' or new.status is distinct from old.status then
    select user_id into v_user from public.srk_worker_profiles where id=new.worker_id;
    insert into public.srk_app_notifications(user_id,notification_type,title,body)
    values(v_user,'payout_status','Payout status updated',
      'Your payout '||coalesce(new.payout_code,'')||' is now: '||new.status||
      case when new.payment_reference is not null then '. Reference: '||new.payment_reference else '' end);
  end if;
  return new;
end $$;
drop trigger if exists srk_worker_payout_notification_trigger on public.srk_worker_payout_requests;
create trigger srk_worker_payout_notification_trigger after insert or update of status on public.srk_worker_payout_requests
for each row execute function public.srk_on_worker_payout_notification();

create or replace function public.srk_on_worker_earning_notification()
returns trigger language plpgsql security definer
set search_path=pg_catalog,public
as $$
declare v_user uuid;
begin
  if new.settlement_status in ('available','cash_commission_due','cash_split_pending') then
    select user_id into v_user from public.srk_worker_profiles where id=new.worker_id;
    insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
    values(v_user,'earning_status','Booking earning updated',
      'Your earning settlement status is: '||new.settlement_status,new.booking_id);
  end if;
  return new;
end $$;
drop trigger if exists srk_worker_earning_notification_trigger on public.srk_worker_earnings;
create trigger srk_worker_earning_notification_trigger after insert or update of settlement_status on public.srk_worker_earnings
for each row execute function public.srk_on_worker_earning_notification();

revoke all on function public.srk_notify_admin_permission_team() from public,anon,authenticated;
revoke all on function public.srk_on_worker_payout_notification() from public,anon,authenticated;
revoke all on function public.srk_on_worker_earning_notification() from public,anon,authenticated;

create or replace function public.srk_on_emergency_notification()
returns trigger language plpgsql security definer
set search_path=pg_catalog,public
as $$
begin
  insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
  select user_id,'admin_action_required','Emergency Alert','An emergency alert requires immediate Admin attention.',new.booking_id
  from public.srk_admin_users
  union
  select sm.user_id,'admin_action_required','Emergency Alert','An emergency alert requires immediate Admin attention.',new.booking_id
  from public.srk_admin_staff_members sm
  join public.srk_admin_roles r on r.id=sm.role_id and r.is_active
  join public.srk_admin_role_permissions rp on rp.role_id=r.id and rp.permission_code='support.manage'
  where sm.is_active;
  return new;
end $$;

create or replace function public.srk_create_support_case(
 p_booking_id uuid,p_category text,p_subject text,p_description text,p_priority text default 'normal'
) returns public.srk_support_cases
language plpgsql security definer
set search_path=pg_catalog,public,auth
as $$
declare v_role text; v_case public.srk_support_cases%rowtype;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if p_booking_id is not null then
    if exists(select 1 from public.service_bookings where id=p_booking_id and customer_user_id=auth.uid()) then v_role:='customer';
    else
      select w.worker_type into v_role from public.srk_booking_workers bw join public.srk_worker_profiles w on w.id=bw.worker_id
      where bw.booking_id=p_booking_id and w.user_id=auth.uid() limit 1;
    end if;
  else
    if exists(select 1 from public.srk_customer_profiles where user_id=auth.uid()) then v_role:='customer';
    else select worker_type into v_role from public.srk_worker_profiles where user_id=auth.uid(); end if;
  end if;
  if v_role is null then raise exception 'Customer or worker profile required'; end if;
  insert into public.srk_support_cases(booking_id,raised_by,raised_by_role,category,subject,description,priority)
  values(p_booking_id,auth.uid(),v_role,p_category,p_subject,p_description,p_priority) returning * into v_case;
  insert into public.srk_support_case_events(case_id,actor_user_id,action,new_status,note)
  values(v_case.id,auth.uid(),'case_created','open',p_description);
  return v_case;
end $$;

create or replace function public.srk_raise_payment_dispute(p_booking_id uuid,p_dispute_type text,p_description text)
returns public.srk_booking_payment_disputes
language plpgsql security definer
set search_path=pg_catalog,public,auth
as $$
declare v_role text; v public.srk_booking_payment_disputes%rowtype;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if exists(select 1 from public.service_bookings where id=p_booking_id and customer_user_id=auth.uid()) then v_role:='customer';
  else
    select w.worker_type into v_role from public.srk_booking_workers bw join public.srk_worker_profiles w on w.id=bw.worker_id
    where bw.booking_id=p_booking_id and w.user_id=auth.uid() limit 1;
    if v_role is null then raise exception 'Only booking customer or assigned worker can report payment dispute'; end if;
  end if;
  insert into public.srk_booking_payment_disputes(booking_id,raised_by,raised_by_role,dispute_type,description)
  values(p_booking_id,auth.uid(),v_role,p_dispute_type,p_description) returning * into v;
  return v;
end $$;

create or replace function public.srk_on_refund_status_notification()
returns trigger language plpgsql security definer
set search_path=pg_catalog,public
as $$
declare v_customer uuid;
begin
  if tg_op='INSERT' or new.status is distinct from old.status then
    select customer_user_id into v_customer from public.service_bookings where id=new.booking_id;
    if v_customer is not null then
      insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
      values(v_customer,'refund_status','Refund status updated','Your refund request is now: '||new.status,new.booking_id);
    end if;
    insert into public.srk_app_notifications(user_id,notification_type,title,body,related_booking_id)
    select w.user_id,'refund_review','Booking refund review','A refund request for your booking is now: '||new.status,new.booking_id
    from public.srk_booking_workers bw join public.srk_worker_profiles w on w.id=bw.worker_id
    where bw.booking_id=new.booking_id;
  end if;
  return new;
end $$;
drop trigger if exists srk_refund_status_notification_trigger on public.srk_booking_refund_requests;
create trigger srk_refund_status_notification_trigger
after insert or update of status on public.srk_booking_refund_requests
for each row execute function public.srk_on_refund_status_notification();
revoke all on function public.srk_on_refund_status_notification() from public,anon,authenticated;

create unique index if not exists srk_one_customer_rating_per_booking
on public.srk_booking_ratings(booking_id,rater_user_id)
